#!/usr/bin/env node
/**
 * Seed users exactly as the app's Stripe checkout webhook
 * (app/api/webhooks/stripe/route.ts, event "checkout.session.completed")
 * leaves them after a successful subscription checkout:
 *
 *   stripeSubscriptionId   = subscription.id
 *   stripeCustomerId       = subscription.customer
 *   stripePriceId          = subscription.items.data[0].price.id
 *   stripeCurrentPeriodEnd = new Date(subscription.current_period_end * 1000)
 *
 * Usage: cd /root/app && node /root/mq/seed.js /root/mq/seed.json
 */
const fs = require("fs")
const path = require("path")

const APP_DIR = "/root/app"

// --- Load DATABASE_URL from /root/app/.env without printing secrets ---------
function loadEnv(appDir) {
  const envPath = path.join(appDir, ".env")
  if (!fs.existsSync(envPath)) return
  const raw = fs.readFileSync(envPath, "utf8")
  for (const line of raw.split(/\r?\n/)) {
    const m = line.match(/^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)\s*$/)
    if (!m) continue
    const key = m[1]
    let val = m[2].trim()
    if (
      (val.startsWith('"') && val.endsWith('"')) ||
      (val.startsWith("'") && val.endsWith("'"))
    ) {
      val = val.slice(1, -1)
    }
    if (process.env[key] === undefined) process.env[key] = val
  }
}
loadEnv(APP_DIR)

if (!process.env.DATABASE_URL) {
  console.error("DATABASE_URL not found (checked /root/app/.env)")
  process.exit(1)
}

// --- Prisma client from the app's node_modules ------------------------------
const { PrismaClient } = require(path.join(APP_DIR, "node_modules", "@prisma", "client"))
const db = new PrismaClient()

function toDate(seconds) {
  if (seconds === null || seconds === undefined || seconds === "") return null
  const n = Number(seconds)
  if (!Number.isFinite(n)) throw new Error(`Invalid unix seconds: ${seconds}`)
  // Webhook: new Date(subscription.current_period_end * 1000)
  return new Date(n * 1000)
}

function nullIfEmpty(v) {
  return v === undefined || v === null || v === "" ? null : v
}

async function main() {
  const file = process.argv[2]
  if (!file) {
    console.error("Usage: node /root/mq/seed.js <seed.json>")
    process.exit(1)
  }
  const entries = JSON.parse(fs.readFileSync(file, "utf8"))
  if (!Array.isArray(entries)) throw new Error("seed file must be a JSON array")

  const results = []
  for (const e of entries) {
    if (!e || !e.email) throw new Error(`Entry missing email: ${JSON.stringify(e)}`)

    // Same field mapping as the checkout.session.completed handler.
    const stripeData = {
      stripeSubscriptionId: nullIfEmpty(e.stripeSubscriptionId),
      stripeCustomerId: nullIfEmpty(e.stripeCustomerId),
      stripePriceId: nullIfEmpty(e.stripePriceId),
      stripeCurrentPeriodEnd: toDate(e.stripeCurrentPeriodEnd),
    }

    const user = await db.user.upsert({
      where: { email: e.email },
      update: {
        name: nullIfEmpty(e.name),
        ...stripeData,
      },
      create: {
        email: e.email,
        name: nullIfEmpty(e.name),
        ...stripeData,
      },
    })
    results.push(user)
  }

  for (const u of results) {
    console.log(
      JSON.stringify({
        id: u.id,
        email: u.email,
        name: u.name,
        stripeCustomerId: u.stripeCustomerId,
        stripeSubscriptionId: u.stripeSubscriptionId,
        stripePriceId: u.stripePriceId,
        stripeCurrentPeriodEnd: u.stripeCurrentPeriodEnd
          ? u.stripeCurrentPeriodEnd.toISOString()
          : null,
      })
    )
  }
  console.log(`Seeded ${results.length} user(s).`)
}

main()
  .catch((err) => {
    console.error("Seed failed:", err.message)
    process.exitCode = 1
  })
  .finally(async () => {
    await db.$disconnect()
  })

