#!/usr/bin/env node
/**
 * Print a Cookie header value that authenticates as an existing user.
 *
 * Usage: cd /root/app && node /root/mq/session.js <email>
 *
 * Mirrors the app's NextAuth config (pages/api/auth/[...nextauth].ts):
 *   session.strategy = "jwt"  ->  JWT session cookie
 *   cookie name on plain http = "next-auth.session-token"
 * Token is produced with next-auth's own encode() and NEXTAUTH_SECRET.
 */
const fs = require("fs")
const path = require("path")

const APP_DIR = "/root/app"

// --- Load /root/app/.env without printing secrets ---------------------------
function loadEnv(appDir) {
  const envPath = path.join(appDir, ".env")
  if (!fs.existsSync(envPath)) return
  const raw = fs.readFileSync(envPath, "utf8")
  for (const line of raw.split(/\r?\n/)) {
    const m = line.match(/^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)\s*$/)
    if (!m) continue
    const key = m[1]
    let val = m[2].trim()
    if (
      (val.startsWith('"') && val.endsWith('"')) ||
      (val.startsWith("'") && val.endsWith("'"))
    ) {
      val = val.slice(1, -1)
    }
    if (process.env[key] === undefined) process.env[key] = val
  }
}
loadEnv(APP_DIR)

const email = process.argv[2]
if (!email) {
  console.error("Usage: node /root/mq/session.js <email>")
  process.exit(1)
}
if (!process.env.NEXTAUTH_SECRET) {
  console.error("NEXTAUTH_SECRET not found (checked /root/app/.env)")
  process.exit(1)
}

const { encode } = require(path.join(APP_DIR, "node_modules", "next-auth", "jwt"))
const { PrismaClient } = require(path.join(APP_DIR, "node_modules", "@prisma", "client"))
const db = new PrismaClient()

async function main() {
  const user = await db.user.findUnique({ where: { email } })
  if (!user) {
    console.error(`No user with email ${email}`)
    process.exit(1)
  }

  // Shape matches what the app's jwt() callback returns for an existing user.
  const token = {
    id: user.id,
    name: user.name,
    email: user.email,
    picture: user.image,
    sub: user.id,
  }

  const jwt = await encode({
    token,
    secret: process.env.NEXTAUTH_SECRET,
    maxAge: 30 * 24 * 60 * 60, // NextAuth default session maxAge
  })

  // Plain http -> non-secure cookie name.
  const cookieName = "next-auth.session-token"
  process.stdout.write(`${cookieName}=${jwt}\n`)
}

main()
  .catch((err) => {
    console.error("session.js failed:", err.message)
    process.exitCode = 1
  })
  .finally(async () => {
    await db.$disconnect()
  })

